screenPanels.initJs:
function(container, apiUrl, tables) {
  let currentOrderId = null;

  // KPI更新関数
  function updateKPIs(orders) {
    const totalOrders = orders.length;
    const currentMonth = new Date().toISOString().slice(0, 7);
    const monthlyAmount = orders
      .filter(o => o.発注日 && o.発注日.slice(0, 7) === currentMonth)
      .reduce((sum, o) => sum + (o.発注金額 || 0), 0);
    const errorCount = orders.filter(o => o.発注ステータス === 'エラー').length;
    const pendingCount = orders.filter(o => o.発注ステータス === '承認待ち').length;

    container.querySelector('[data-testid="kpi-total-orders"]').textContent = totalOrders.toLocaleString();
    container.querySelector('[data-testid="kpi-monthly-amount"]').textContent = '¥' + monthlyAmount.toLocaleString();
    container.querySelector('[data-testid="kpi-error-count"]').textContent = errorCount.toLocaleString();
    container.querySelector('[data-testid="kpi-pending-count"]').textContent = pendingCount.toLocaleString();
  }

  // グラフ初期化
  function initCharts(orders) {
    // 月別発注金額推移
    const monthlyData = {};
    orders.forEach(order => {
      if (order.発注日) {
        const month = order.発注日.slice(0, 7);
        monthlyData[month] = (monthlyData[month] || 0) + (order.発注金額 || 0);
      }
    });

    const sortedMonths = Object.keys(monthlyData).sort().slice(-6);
    const monthlyChart = new Chart(container.querySelector('#monthly-chart'), {
      type: 'line',
      data: {
        labels: sortedMonths,
        datasets: [{
          label: '発注金額',
          data: sortedMonths.map(m => monthlyData[m]),
          borderColor: '#10b981',
          backgroundColor: 'rgba(16, 185, 129, 0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            ticks: {
              callback: function(value) {
                return '¥' + value.toLocaleString();
              }
            }
          }
        }
      }
    });

    // ステータス分布
    const statusData = {};
    orders.forEach(order => {
      const status = order.発注ステータス || '不明';
      statusData[status] = (statusData[status] || 0) + 1;
    });

    const statusChart = new Chart(container.querySelector('#status-chart'), {
      type: 'doughnut',
      data: {
        labels: Object.keys(statusData),
        datasets: [{
          data: Object.values(statusData),
          backgroundColor: ['#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#84cc16']
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false
      }
    });
  }

  // テーブル再描画関数
  function renderOrders(orders) {
    const tbody = container.querySelector('#order-tbody');
    tbody.innerHTML = orders.map(order => {
      const integrationStatus = Math.random() > 0.7 ? 'エラー' : Math.random() > 0.5 ? '連携済み' : '未連携';
      const statusColor = order.発注ステータス === '完了' ? '#10b981' : 
                         order.発注ステータス === '承認待ち' ? '#f59e0b' : 
                         order.発注ステータス === 'キャンセル' ? '#ef4444' : 'var(--text)';
      const integrationColor = integrationStatus === 'エラー' ? '#ef4444' : 
                              integrationStatus === '連携済み' ? '#10b981' : '#f59e0b';

      return `
        <tr data-id="${order.発注ID}" class="cursor-pointer hover:bg-opacity-50" style="background: var(--bg-card);">
          <td>${order.発注番号 || ''}</td>
          <td>${order.発注日 ? order.発注日.slice(0, 10) : ''}</td>
          <td>${order.発注者名 || ''}</td>
          <td>${order.発注先名 || ''}</td>
          <td>¥${(order.発注金額 || 0).toLocaleString()}</td>
          <td><span style="color: ${statusColor}; font-weight: 500;">${order.発注ステータス || ''}</span></td>
          <td><span style="color: ${integrationColor}; font-weight: 500;">${integrationStatus}</span></td>
          <td>
            <button class="action-btn secondary detail-btn text-xs px-2 py-1" data-id="${order.発注ID}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');

    updateKPIs(orders);
  }

  // 検索関数
  function searchOrders() {
    const orderNumber = container.querySelector('#search-order-number').value;
    const dateFrom = container.querySelector('#search-date-from').value;
    const dateTo = container.querySelector('#search-date-to').value;
    const status = container.querySelector('#search-status').value;
    const integration = container.querySelector('#search-integration').value;

    window.aivicApi.list(1).then(orders => {
      if (!orders) return;

      let filtered = orders.filter(order => {
        if (orderNumber && !order.発注番号?.includes(orderNumber)) return false;
        if (dateFrom && order.発注日 && order.発注日 < dateFrom) return false;
        if (dateTo && order.発注日 && order.発注日 > dateTo) return false;
        if (status && order.発注ステータス !== status) return false;
        return true;
      });

      renderOrders(filtered);
    });
  }

  // 詳細モーダル表示
  function showOrderDetail(orderId) {
    window.aivicApi.list(1).then(orders => {
      if (!orders) return;

      const order = orders.find(o => o.発注ID === orderId);
      if (!order) return;

      currentOrderId = orderId;

      // 基本情報設定
      container.querySelector('#detail-order-number').textContent = order.発注番号 || '';
      container.querySelector('#detail-order-date').textContent = order.発注日 ? order.発注日.slice(0, 10) : '';
      container.querySelector('#detail-delivery-date').textContent = order.希望納期 ? order.希望納期.slice(0, 10) : '';
      container.querySelector('#detail-supplier').textContent = order.発注先名 || '';
      container.querySelector('#detail-amount').textContent = '¥' + (order.発注金額 || 0).toLocaleString();
      container.querySelector('#detail-status').textContent = order.発注ステータス || '';

      // 連携・検証状況（サンプル）
      const integrationStatus = Math.random() > 0.5 ? '連携済み' : '未連携';
      const validationStatus = Math.random() > 0.5 ? '検証完了' : '検証中';
      container.querySelector('#integration-result').textContent = integrationStatus;
      container.querySelector('#validation-result').textContent = validationStatus;

      // 発注明細取得・表示
      window.aivicApi.list(2).then(details => {
        if (!details) return;

        const orderDetails = details.filter(d => d.発注ID === orderId);
        const detailTbody = container.querySelector('#detail-tbody');
        detailTbody.innerHTML = orderDetails.map(detail => `
          <tr>
            <td>${detail.明細番号 || ''}</td>
            <td>${detail.商品コード || ''}</td>
            <td>${detail.商品名 || ''}</td>
            <td>${(detail.発注数量 || 0).toLocaleString()}</td>
            <td>${detail.単位 || ''}</td>
            <td>¥${(detail.単価 || 0).toLocaleString()}</td>
            <td>¥${(detail.金額 || 0).toLocaleString()}</td>
            <td>${detail.明細ステータス || ''}</td>
          </tr>
        `).join('');
      });

      container.querySelector('#order-detail-modal').style.display = 'flex';
    });
  }

  // CSVエクスポート
  function exportCSV() {
    window.aivicApi.list(1).then(orders => {
      if (!orders) return;

      const headers = ['発注番号', '発注日', '発注者', '発注先', '発注金額', 'ステータス', '希望納期'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...orders.map(order => [
          order.発注番号 || '',
          order.発注日 || '',
          order.発注者名 || '',
          order.発注先名 || '',
          order.発注金額 || 0,
          order.発注ステータス || '',
          order.希望納期 || ''
        ].map(field => `"${field}"`).join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `発注データ_${new Date().toISOString().slice(0, 10)}.csv`;
      link.click();
    });
  }

  // 初期データ読み込み・描画
  window.aivicApi.list(1).then(orders => {
    if (orders) {
      renderOrders(orders);
      initCharts(orders);
    }
  });

  // イベントリスナー
  container.querySelector('#btn-search').addEventListener('click', searchOrders);

  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#search-order-number').value = '';
    container.querySelector('#search-date-from').value = '';
    container.querySelector('#search-date-to').value = '';
    container.querySelector('#search-status').value = '';
    container.querySelector('#search-integration').value = '';
    window.aivicApi.list(1).then(orders => {
      if (orders) renderOrders(orders);
    });
  });

  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#order-detail-modal').style.display = 'none';
  });

  // 行クリック・詳細ボタン
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    const row = e.target.closest('tr[data-id]');

    if (detailBtn || (row && !e.target.closest('button'))) {
      const orderId = detailBtn ? detailBtn.dataset.id : row.dataset.id;
      if (orderId) showOrderDetail(orderId);
    }
  });

  // モーダル外クリックで閉じる
  container.querySelector('#order-detail-modal').addEventListener('click', (e) => {
    if (e.target === e.currentTarget) {
      e.currentTarget.style.display = 'none';
    }
  });
}

function(container, apiUrl, tables) {
  // 各テーブルのインデックス
  const HISTORY_TABLE = 5; // 連携処理履歴
  const ERROR_TABLE = 6;   // 連携エラーログ
  const VALIDATION_TABLE = 7; // データ検証結果

  // 再描画関数の定義
  function renderProcessingRows(rows) {
    const tbody = container.querySelector("#processing-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td class="text-xs">${r.連携処理履歴ID?.substring(0, 8) || ""}</td>
        <td class="text-xs">${r.連携設定ID || ""}</td>
        <td class="text-xs">${r.処理種別 || ""}</td>
        <td class="text-xs">${r.処理開始日時 ? new Date(r.処理開始日時).toLocaleString() : ""}</td>
        <td class="text-xs">
          <div class="w-full bg-gray-200 rounded-full h-1.5">
            <div class="bg-blue-600 h-1.5 rounded-full" style="width: ${Math.random() * 100}%"></div>
          </div>
        </td>
        <td class="text-xs">
          <span class="px-2 py-0.5 rounded text-xs" style="background: ${r.処理ステータス === '実行中' ? '#fef3c7' : r.処理ステータス === '成功' ? '#d1fae5' : '#fee2e2'}; color: ${r.処理ステータス === '実行中' ? '#92400e' : r.処理ステータス === '成功' ? '#065f46' : '#991b1b'};">
            ${r.処理ステータス || ""}
          </span>
        </td>
        <td class="text-xs">
          <button class="action-btn secondary text-xs px-2 py-1 cancel-btn" data-id="${r.id}">中断</button>
        </td>
      </tr>
    `).join("");
  }

  function renderHistoryRows(rows) {
    const tbody = container.querySelector("#history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td class="text-xs">${r.処理開始日時 ? new Date(r.処理開始日時).toLocaleString() : ""}</td>
        <td class="text-xs">${r.連携設定ID || ""}</td>
        <td class="text-xs">${r.処理種別 || ""}</td>
        <td class="text-xs">
          <span class="px-2 py-0.5 rounded text-xs" style="background: ${r.処理ステータス === '成功' ? '#d1fae5' : '#fee2e2'}; color: ${r.処理ステータス === '成功' ? '#065f46' : '#991b1b'};">
            ${r.処理ステータス || ""}
          </span>
        </td>
        <td class="text-xs">${r.処理件数 || 0}</td>
        <td class="text-xs">${r.成功件数 || 0}</td>
        <td class="text-xs">${r.エラー件数 || 0}</td>
        <td class="text-xs">
          <button class="action-btn secondary text-xs px-2 py-1 detail-btn" data-id="${r.id}">詳細</button>
        </td>
      </tr>
    `).join("");
  }

  function renderErrorRows(rows) {
    const tbody = container.querySelector("#errors-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td class="text-xs">${r.エラー発生日時 ? new Date(r.エラー発生日時).toLocaleString() : ""}</td>
        <td class="text-xs">${r.エラー種別 || ""}</td>
        <td class="text-xs" title="${r.エラーメッセージ || ""}">${(r.エラーメッセージ || "").substring(0, 30)}${(r.エラーメッセージ || "").length > 30 ? "..." : ""}</td>
        <td class="text-xs">
          <span class="px-2 py-0.5 rounded text-xs" style="background: ${r.重要度 === '緊急' ? '#fee2e2' : r.重要度 === '高' ? '#fef3c7' : '#f3f4f6'}; color: ${r.重要度 === '緊急' ? '#991b1b' : r.重要度 === '高' ? '#92400e' : '#374151'};">
            ${r.重要度 || ""}
          </span>
        </td>
        <td class="text-xs">${r.対応状況 || ""}</td>
        <td class="text-xs">
          <button class="action-btn secondary text-xs px-2 py-1 resolve-btn" data-id="${r.id}">対応</button>
        </td>
      </tr>
    `).join("");
  }

  function renderValidationRows(rows) {
    const tbody = container.querySelector("#validation-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td class="text-xs">${r.検証実行日時 ? new Date(r.検証実行日時).toLocaleString() : ""}</td>
        <td class="text-xs">${r.検証項目名 || ""}</td>
        <td class="text-xs">
          <span class="px-2 py-0.5 rounded text-xs" style="background: ${r.検証結果 === '成功' ? '#d1fae5' : r.検証結果 === '警告' ? '#fef3c7' : '#fee2e2'}; color: ${r.検証結果 === '成功' ? '#065f46' : r.検証結果 === '警告' ? '#92400e' : '#991b1b'};">
            ${r.検証結果 || ""}
          </span>
        </td>
        <td class="text-xs">${r.検証メッセージ || ""}</td>
        <td class="text-xs">${r.重要度 || ""}</td>
        <td class="text-xs">${r.処理継続可否 ? "可" : "不可"}</td>
      </tr>
    `).join("");
  }

  // 統計情報の更新
  function updateStats() {
    window.aivicApi.list(HISTORY_TABLE).then(rows => {
      if (rows) {
        const completed = rows.filter(r => r.処理ステータス === '成功').length;
        const errors = rows.filter(r => r.処理ステータス === '失敗').length;
        const processing = rows.filter(r => r.処理ステータス === '実行中').length;

        container.querySelector("#completed-count").textContent = completed;
        container.querySelector("#error-count").textContent = errors;
        container.querySelector("#processing-count").textContent = processing;
      }
    });
  }

  // 初期データ読み込み
  window.aivicApi.list(HISTORY_TABLE).then(rows => {
    if (rows) {
      const processingRows = rows.filter(r => r.処理ステータス === '実行中');
      renderProcessingRows(processingRows);
      renderHistoryRows(rows);
      updateStats();
    }
  });

  window.aivicApi.list(ERROR_TABLE).then(rows => {
    if (rows) renderErrorRows(rows);
  });

  window.aivicApi.list(VALIDATION_TABLE).then(rows => {
    if (rows) renderValidationRows(rows);
  });

  // タブ切り替え
  function switchTab(activeTabId) {
    const tabs = ['history', 'errors', 'validation'];
    tabs.forEach(tab => {
      const tabBtn = container.querySelector(`#tab-${tab}`);
      const panel = container.querySelector(`#${tab}-panel`);

      if (tab === activeTabId) {
        tabBtn.style.color = 'var(--primary)';
        tabBtn.style.borderColor = 'var(--primary)';
        panel.style.display = 'block';
      } else {
        tabBtn.style.color = 'var(--text-muted)';
        tabBtn.style.borderColor = 'transparent';
        panel.style.display = 'none';
      }
    });
  }

  container.querySelector("#tab-history").addEventListener("click", () => switchTab('history'));
  container.querySelector("#tab-errors").addEventListener("click", () => switchTab('errors'));
  container.querySelector("#tab-validation").addEventListener("click", () => switchTab('validation'));

  // 検索機能
  container.querySelector("#btn-search").addEventListener("click", () => {
    const keyword = container.querySelector("#search-input").value.toLowerCase();
    window.aivicApi.list(HISTORY_TABLE).then(rows => {
      if (rows) {
        const filtered = rows.filter(r => 
          JSON.stringify(r).toLowerCase().includes(keyword)
        );
        const processingRows = filtered.filter(r => r.処理ステータス === '実行中');
        renderProcessingRows(processingRows);
        renderHistoryRows(filtered);
      }
    });
  });

  // 連携処理実行
  container.querySelector("#btn-execute").addEventListener("click", async () => {
    const targetSystem = container.querySelector("#target-system").value;
    const processType = container.querySelector("#process-type").value;
    const startDateTime = container.querySelector("#start-datetime").value;
    const endDateTime = container.querySelector("#end-datetime").value;

    if (!targetSystem || !processType) {
      alert("連携対象システムと処理種別を選択してください");
      return;
    }

    const newProcess = {
      連携設定ID: targetSystem,
      処理種別: processType === 'manual' ? '手動実行' : processType === 'auto' ? '自動処理' : 'スケジュール実行',
      処理ステータス: '実行中',
      処理開始日時: new Date().toISOString(),
      処理件数: 0,
      成功件数: 0,
      エラー件数: 0,
      再試行回数: 0
    };

    const saved = await window.aivicApi.save(HISTORY_TABLE, newProcess);
    if (saved) {
      window.aivicApi.list(HISTORY_TABLE).then(rows => {
        if (rows) {
          const processingRows = rows.filter(r => r.処理ステータス === '実行中');
          renderProcessingRows(processingRows);
          renderHistoryRows(rows);
          updateStats();
        }
      });

      // フォームリセット
      container.querySelector("#target-system").value = "";
      container.querySelector("#process-type").value = "";
      container.querySelector("#start-datetime").value = "";
      container.querySelector("#end-datetime").value = "";
    }
  });

  // 再処理実行
  container.querySelector("#btn-retry").addEventListener("click", async () => {
    if (!confirm("エラー分の再処理を実行しますか？")) return;

    // エラー状態の処理を再実行状態に更新
    window.aivicApi.list(HISTORY_TABLE).then(async rows => {
      if (rows) {
        const errorRows = rows.filter(r => r.処理ステータス === '失敗');
        for (const row of errorRows) {
          await window.aivicApi.update(HISTORY_TABLE, row.id, {
            処理ステータス: '実行中',
            再試行回数: (row.再試行回数 || 0) + 1
          });
        }

        // 再描画
        window.aivicApi.list(HISTORY_TABLE).then(updatedRows => {
          if (updatedRows) {
            const processingRows = updatedRows.filter(r => r.処理ステータス === '実行中');
            renderProcessingRows(processingRows);
            renderHistoryRows(updatedRows);
            updateStats();
          }
        });
      }
    });
  });

  // CSVエクスポート
  container.querySelector("#btn-export-csv").addEventListener("click", () => {
    window.aivicApi.list(HISTORY_TABLE).then(rows => {
      if (rows) {
        const headers = ['処理日時', 'システム名', '処理種別', 'ステータス', '処理件数', '成功件数', 'エラー件数'];
        const csvData = [
          headers.join(','),
          ...rows.map(r => [
            r.処理開始日時 ? new Date(r.処理開始日時).toLocaleString() : '',
            r.連携設定ID || '',
            r.処理種別 || '',
            r.処理ステータス || '',
            r.処理件数 || 0,
            r.成功件数 || 0,
            r.エラー件数 || 0
          ].map(field => `"${field}"`).join(','))
        ].join('\n');

        const blob = new Blob(['\uFEFF' + csvData], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = '連携処理履歴.csv';
        link.click();
      }
    });
  });

  // 画面遷移
  container.querySelector("#btn-view-history").addEventListener("click", () => {
    window.showScreen("scr-1780291323940");
  });

  container.querySelector("#btn-view-errors").addEventListener("click", () => {
    window.showScreen("scr-1780291305048");
  });

  container.querySelector("#btn-view-validation").addEventListener("click", () => {
    window.showScreen("scr-1780291315061");
  });

  // イベントデリゲーション
  container.addEventListener("click", async (e) => {
    const cancelBtn = e.target.closest(".cancel-btn");
    if (cancelBtn) {
      if (!confirm("処理を中断しますか？")) return;
      await window.aivicApi.update(HISTORY_TABLE, cancelBtn.dataset.id, {
        処理ステータス: '中断',
        処理終了日時: new Date().toISOString()
      });

      window.aivicApi.list(HISTORY_TABLE).then(rows => {
        if (rows) {
          const processingRows = rows.filter(r => r.処理ステータス === '実行中');
          renderProcessingRows(processingRows);
          renderHistoryRows(rows);
          updateStats();
        }
      });
    }

    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      window.showScreen("scr-1780291323940");
    }

    const resolveBtn = e.target.closest(".resolve-btn");
    if (resolveBtn) {
      await window.aivicApi.update(ERROR_TABLE, resolveBtn.dataset.id, {
        対応状況: '対応中',
        対応開始日時: new Date().toISOString()
      });

      window.aivicApi.list(ERROR_TABLE).then(rows => {
        if (rows) renderErrorRows(rows);
      });
    }
  });
}

function(container, apiUrl, tables) {
  let currentErrors = [];
  let selectedErrorId = null;

  // 再描画関数の定義
  function renderErrors(errors) {
    const tbody = container.querySelector("#error-tbody");
    tbody.innerHTML = errors.map(error => `
      <tr data-id="${error.id}">
        <td><input type="checkbox" class="error-checkbox" data-id="${error.id}"></td>
        <td>${new Date(error.エラー発生日時).toLocaleString()}</td>
        <td>
          <span class="px-2 py-1 text-xs rounded" style="background: ${getErrorTypeColor(error.エラー種別)}; color: #fff;">
            ${error.エラー種別}
          </span>
        </td>
        <td>${error.連携システム || '-'}</td>
        <td>${error.発注データID ? `発注-${error.発注データID.slice(0,8)}` : '-'}</td>
        <td class="max-w-xs truncate">${error.エラーメッセージ}</td>
        <td>
          <span class="px-2 py-1 text-xs rounded" style="background: ${getSeverityColor(error.重要度)}; color: #fff;">
            ${error.重要度}
          </span>
        </td>
        <td>
          <span class="px-2 py-1 text-xs rounded" style="background: ${getStatusColor(error.対応状況)}; color: #fff;">
            ${error.対応状況}
          </span>
        </td>
        <td>${error.対応者名 || '-'}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${error.id}">詳細</button>
        </td>
      </tr>
    `).join("");

    updateSummary(errors);
  }

  function getErrorTypeColor(type) {
    const colors = {
      'システムエラー': '#dc3545',
      'データ検証エラー': '#fd7e14',
      '通信エラー': '#6f42c1',
      '認証エラー': '#e83e8c'
    };
    return colors[type] || '#6c757d';
  }

  function getSeverityColor(severity) {
    const colors = {
      '緊急': '#dc3545',
      '高': '#fd7e14',
      '中': '#ffc107',
      '低': '#28a745'
    };
    return colors[severity] || '#6c757d';
  }

  function getStatusColor(status) {
    const colors = {
      '未対応': '#dc3545',
      '対応中': '#ffc107',
      '対応完了': '#28a745',
      '保留': '#6c757d'
    };
    return colors[status] || '#6c757d';
  }

  function updateSummary(errors) {
    const total = errors.length;
    const pending = errors.filter(e => e.対応状況 === '未対応').length;
    const processing = errors.filter(e => e.対応状況 === '対応中').length;
    const completed = errors.filter(e => e.対応状況 === '対応完了').length;

    container.querySelector("#total-errors").textContent = total;
    container.querySelector("#pending-errors").textContent = pending;
    container.querySelector("#processing-errors").textContent = processing;
    container.querySelector("#completed-errors").textContent = completed;
  }

  function drawTrendChart(errors) {
    const canvas = container.querySelector("#trend-chart");
    const ctx = canvas.getContext("2d");

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 簡単な時系列グラフ
    const days = 7;
    const data = [];
    const today = new Date();

    for (let i = days - 1; i >= 0; i--) {
      const date = new Date(today);
      date.setDate(date.getDate() - i);
      const dayErrors = errors.filter(e => {
        const errorDate = new Date(e.エラー発生日時);
        return errorDate.toDateString() === date.toDateString();
      }).length;
      data.push({ date: date.getDate(), count: dayErrors });
    }

    const maxCount = Math.max(...data.map(d => d.count), 1);
    const chartHeight = 150;
    const chartWidth = 350;
    const barWidth = chartWidth / days;

    // グラフ描画
    ctx.fillStyle = '#28a745';
    data.forEach((d, i) => {
      const height = (d.count / maxCount) * chartHeight;
      ctx.fillRect(i * barWidth + 10, chartHeight - height + 20, barWidth - 2, height);
    });

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '10px sans-serif';
    data.forEach((d, i) => {
      ctx.fillText(d.date.toString(), i * barWidth + 15, chartHeight + 40);
      if (d.count > 0) {
        ctx.fillText(d.count.toString(), i * barWidth + 15, chartHeight - (d.count / maxCount) * chartHeight + 15);
      }
    });
  }

  function drawCategoryChart(errors) {
    const canvas = container.querySelector("#category-chart");
    const ctx = canvas.getContext("2d");

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const categories = {};
    errors.forEach(e => {
      categories[e.エラー種別] = (categories[e.エラー種別] || 0) + 1;
    });

    const total = errors.length;
    if (total === 0) return;

    const centerX = 200;
    const centerY = 100;
    const radius = 80;

    let startAngle = 0;
    const colors = ['#28a745', '#ffc107', '#dc3545', '#6f42c1'];
    let colorIndex = 0;

    Object.entries(categories).forEach(([category, count]) => {
      const sliceAngle = (count / total) * 2 * Math.PI;

      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.arc(centerX, centerY, radius, startAngle, startAngle + sliceAngle);
      ctx.closePath();
      ctx.fillStyle = colors[colorIndex % colors.length];
      ctx.fill();

      // ラベル
      const labelAngle = startAngle + sliceAngle / 2;
      const labelX = centerX + Math.cos(labelAngle) * (radius + 20);
      const labelY = centerY + Math.sin(labelAngle) * (radius + 20);

      ctx.fillStyle = '#9fb0d1';
      ctx.font = '10px sans-serif';
      ctx.fillText(`${category} (${count})`, labelX - 30, labelY);

      startAngle += sliceAngle;
      colorIndex++;
    });
  }

  // 初期データ読み込み
  window.aivicApi.list(6).then(errors => {
    if (errors) {
      currentErrors = errors;
      renderErrors(errors);
      drawTrendChart(errors);
      drawCategoryChart(errors);
    }
  });

  // 検索機能
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const dateFrom = container.querySelector("#date-from").value;
    const dateTo = container.querySelector("#date-to").value;
    const errorType = container.querySelector("#error-type-filter").value;
    const system = container.querySelector("#system-filter").value;

    const errors = await window.aivicApi.list(6);
    if (!errors) return;

    let filtered = errors.filter(error => {
      if (dateFrom && new Date(error.エラー発生日時) < new Date(dateFrom)) return false;
      if (dateTo && new Date(error.エラー発生日時) > new Date(dateTo + 'T23:59:59')) return false;
      if (errorType && error.エラー種別 !== errorType) return false;
      if (system && error.連携システム !== system) return false;
      return true;
    });

    currentErrors = filtered;
    renderErrors(filtered);
    drawTrendChart(filtered);
    drawCategoryChart(filtered);
  });

  // CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const errors = await window.aivicApi.list(6);
    if (!errors) return;

    const headers = ['エラーログID', 'エラー発生日時', 'エラー種別', 'エラーメッセージ', '重要度', '対応状況', '対応者ID'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...errors.map(error => [
        error.id,
        error.エラー発生日時,
        error.エラー種別,
        `"${error.エラーメッセージ.replace(/"/g, '""')}"`,
        error.重要度,
        error.対応状況,
        error.対応者ID || ''
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `連携エラー一覧_${new Date().toISOString().slice(0,10)}.csv`;
    link.click();
  });

  // 全選択チェックボックス
  container.querySelector("#select-all").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll(".error-checkbox");
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 再処理実行
  container.querySelector("#btn-reprocess").addEventListener("click", async () => {
    const selectedIds = Array.from(container.querySelectorAll(".error-checkbox:checked"))
      .map(cb => cb.dataset.id);

    if (selectedIds.length === 0) {
      alert("再処理するエラーを選択してください");
      return;
    }

    if (!confirm(`選択した${selectedIds.length}件のエラーを再処理しますか？`)) return;

    // 再処理フラグを更新
    for (const id of selectedIds) {
      await window.aivicApi.update(6, id, {
        対応状況: '対応中',
        再処理実行日時: new Date().toISOString()
      });
    }

    // 一覧を再読み込み
    const errors = await window.aivicApi.list(6);
    if (errors) {
      currentErrors = errors;
      renderErrors(errors);
    }
  });

  // ログダウンロード
  container.querySelector("#btn-download-log").addEventListener("click", () => {
    const selectedIds = Array.from(container.querySelectorAll(".error-checkbox:checked"))
      .map(cb => cb.dataset.id);

    if (selectedIds.length === 0) {
      alert("ダウンロードするエラーを選択してください");
      return;
    }

    const selectedErrors = currentErrors.filter(e => selectedIds.includes(e.id));
    const logContent = selectedErrors.map(error => 
      `[${error.エラー発生日時}] ${error.エラー種別}: ${error.エラーメッセージ}\n` +
      `スタックトレース: ${error.スタックトレース || 'なし'}\n` +
      `処理対象データ: ${error.処理対象データ || 'なし'}\n` +
      '---\n'
    ).join('\n');

    const blob = new Blob([logContent], { type: 'text/plain;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `エラーログ_${new Date().toISOString().slice(0,10)}.txt`;
    link.click();
  });

  // エラー詳細モーダル
  container.addEventListener("click", async (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const errorId = detailBtn.dataset.id;
      const error = currentErrors.find(e => e.id === errorId);
      if (!error) return;

      selectedErrorId = errorId;

      // モーダルにデータを設定
      container.querySelector("#modal-error-id").textContent = error.id;
      container.querySelector("#modal-error-date").textContent = new Date(error.エラー発生日時).toLocaleString();
      container.querySelector("#modal-error-type").textContent = error.エラー種別;
      container.querySelector("#modal-severity").textContent = error.重要度;
      container.querySelector("#modal-error-message").textContent = error.エラーメッセージ;
      container.querySelector("#modal-target-data").textContent = error.処理対象データ || 'データなし';
      container.querySelector("#modal-status").value = error.対応状況;
      container.querySelector("#modal-assignee").value = error.対応者ID || '';
      container.querySelector("#modal-response-content").value = error.対応内容 || '';

      // モーダルを表示
      container.querySelector("#error-detail-modal").style.display = "flex";
    }
  });

  // モーダルを閉じる
  container.querySelector("#close-modal").addEventListener("click", () => {
    container.querySelector("#error-detail-modal").style.display = "none";
  });

  // 対応状況更新
  container.querySelector("#btn-update-status").addEventListener("click", async () => {
    if (!selectedErrorId) return;

    const status = container.querySelector("#modal-status").value;
    const assignee = container.querySelector("#modal-assignee").value;
    const content = container.querySelector("#modal-response-content").value;

    const updateData = {
      対応状況: status,
      対応者ID: assignee,
      対応内容: content
    };

    if (status === '対応中' && !updateData.対応開始日時) {
      updateData.対応開始日時 = new Date().toISOString();
    }
    if (status === '対応完了') {
      updateData.対応完了日時 = new Date().toISOString();
    }

    const updated = await window.aivicApi.update(6, selectedErrorId, updateData);
    if (updated) {
      // 一覧を再読み込み
      const errors = await window.aivicApi.list(6);
      if (errors) {
        currentErrors = errors;
        renderErrors(errors);
      }
      container.querySelector("#error-detail-modal").style.display = "none";
    }
  });

  // 関連発注データ表示
  container.querySelector("#btn-view-order").addEventListener("click", () => {
    const error = currentErrors.find(e => e.id === selectedErrorId);
    if (error && error.発注データID) {
      window.showScreen("scr-1780291283309");
    } else {
      alert("関連する発注データがありません");
    }
  });

  // モーダル外クリックで閉じる
  container.querySelector("#error-detail-modal").addEventListener("click", (e) => {
    if (e.target === e.currentTarget) {
      container.querySelector("#error-detail-modal").style.display = "none";
    }
  });
}

function(container, apiUrl, tables) {
  // 1. 再描画関数の定義
  function renderRows(rows) {
    const tbody = container.querySelector("#validation-results-tbody");

    tbody.innerHTML = rows.map(row => {
      const resultBadge = getResultBadge(row.検証結果 || '');
      const severityBadge = getSeverityBadge(row.重要度 || '');
      const continueBadge = row.処理継続可否 ? 
        '<span class="px-2 py-1 text-xs rounded" style="background: rgba(5, 150, 105, 0.1); color: #059669;">可</span>' :
        '<span class="px-2 py-1 text-xs rounded" style="background: rgba(220, 38, 38, 0.1); color: #dc2626;">不可</span>';

      return `
        <tr data-id="${row.id || ''}">
          <td class="text-xs">${formatDateTime(row.検証実行日時 || '')}</td>
          <td class="text-sm font-medium">${row.発注番号 || ''}</td>
          <td class="text-sm">${row.検証項目名 || ''}</td>
          <td class="text-xs">${row.ルール名 || ''}</td>
          <td>${resultBadge}</td>
          <td>${severityBadge}</td>
          <td class="text-xs max-w-xs truncate">${row.検証メッセージ || ''}</td>
          <td>${continueBadge}</td>
          <td>
            <button class="action-btn secondary detail-btn text-xs px-2 py-1" data-id="${row.id || ''}">詳細</button>
          </td>
        </tr>
      `;
    }).join("");

    updateSummary(rows);
  }

  function getResultBadge(result) {
    switch(result) {
      case '成功':
        return '<span class="px-2 py-1 text-xs rounded" style="background: rgba(5, 150, 105, 0.1); color: #059669;">成功</span>';
      case '警告':
        return '<span class="px-2 py-1 text-xs rounded" style="background: rgba(245, 158, 11, 0.1); color: #f59e0b;">警告</span>';
      case 'エラー':
        return '<span class="px-2 py-1 text-xs rounded" style="background: rgba(220, 38, 38, 0.1); color: #dc2626;">エラー</span>';
      default:
        return '<span class="px-2 py-1 text-xs rounded" style="background: rgba(0,0,0,0.1); color: var(--text-muted);">-</span>';
    }
  }

  function getSeverityBadge(severity) {
    switch(severity) {
      case '高':
        return '<span class="px-2 py-1 text-xs rounded" style="background: rgba(220, 38, 38, 0.1); color: #dc2626;">高</span>';
      case '中':
        return '<span class="px-2 py-1 text-xs rounded" style="background: rgba(245, 158, 11, 0.1); color: #f59e0b;">中</span>';
      case '低':
        return '<span class="px-2 py-1 text-xs rounded" style="background: rgba(107, 114, 128, 0.1); color: #6b7280;">低</span>';
      default:
        return '<span class="px-2 py-1 text-xs rounded" style="background: rgba(0,0,0,0.1); color: var(--text-muted);">-</span>';
    }
  }

  function formatDateTime(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  function updateSummary(rows) {
    const total = rows.length;
    const errorCount = rows.filter(r => r.検証結果 === 'エラー').length;
    const warningCount = rows.filter(r => r.検証結果 === '警告').length;
    const successCount = rows.filter(r => r.検証結果 === '成功').length;

    container.querySelector("#total-count").textContent = total;
    container.querySelector("#error-count").textContent = errorCount;
    container.querySelector("#warning-count").textContent = warningCount;
    container.querySelector("#success-count").textContent = successCount;
  }

  // 2. 初期データを即座に描画
  renderRows(tables[7]?.records || []);

  // 3. 検索ボタンのイベントリスナー
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#input-search").value.toLowerCase();
    const resultFilter = container.querySelector("#filter-result").value;
    const severityFilter = container.querySelector("#filter-severity").value;

    const rows = await window.aivicApi.list(7);
    if (!rows) return;

    const filtered = rows.filter(row => {
      const matchKeyword = !keyword || 
        (row.発注番号 || '').toLowerCase().includes(keyword) ||
        (row.検証項目名 || '').toLowerCase().includes(keyword);
      const matchResult = !resultFilter || row.検証結果 === resultFilter;
      const matchSeverity = !severityFilter || row.重要度 === severityFilter;

      return matchKeyword && matchResult && matchSeverity;
    });

    renderRows(filtered);
  });

  // 4. 再検証実行ボタン
  container.querySelector("#btn-revalidate").addEventListener("click", async () => {
    if (!confirm("再検証を実行しますか？")) return;

    // 実際の実装では連携処理を呼び出し
    alert("再検証処理を開始しました。処理完了後に結果が更新されます。");

    // データを再読み込み
    const rows = await window.aivicApi.list(7);
    if (rows) renderRows(rows);
  });

  // 5. CSV出力ボタン
  container.querySelector("#btn-csv-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(7);
    if (!rows) return;

    const headers = ['検証日時', '発注番号', '検証項目名', '検証ルール', '検証結果', '重要度', '検証メッセージ', '処理継続可否'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...rows.map(row => [
        formatDateTime(row.検証実行日時 || ''),
        row.発注番号 || '',
        row.検証項目名 || '',
        row.ルール名 || '',
        row.検証結果 || '',
        row.重要度 || '',
        `"${(row.検証メッセージ || '').replace(/"/g, '""')}"`,
        row.処理継続可否 ? '可' : '不可'
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `データ検証結果_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  });

  // 6. イベントデリゲーション（詳細表示）
  container.addEventListener("click", async (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      const rows = await window.aivicApi.list(7);
      if (!rows) return;

      const row = rows.find(r => r.id === id);
      if (!row) return;

      // 詳細モーダルに情報を設定
      container.querySelector("#detail-item-name").textContent = row.検証項目名 || '';
      container.querySelector("#detail-before-value").textContent = row.検証前値 || '(なし)';
      container.querySelector("#detail-after-value").textContent = row.検証後値 || '(なし)';
      container.querySelector("#detail-message").textContent = row.検証メッセージ || '';

      // モーダルを表示
      container.querySelector("#detail-modal").style.display = "flex";
    }
  });

  // モーダル閉じるボタン
  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#detail-modal").style.display = "none";
  });

  // モーダル背景クリックで閉じる
  container.querySelector("#detail-modal").addEventListener("click", (e) => {
    if (e.target === container.querySelector("#detail-modal")) {
      container.querySelector("#detail-modal").style.display = "none";
    }
  });
}

function(container, apiUrl, tables) {
  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#history-tbody');
    tbody.innerHTML = rows.map(row => {
