        <tr data-id="${row.id}" class="hover:bg-opacity-50" style="border-bottom: 1px solid var(--border);">
          <td class="px-3 py-2 text-xs" style="color: var(--text);">${startTime}</td>
          <td class="px-3 py-2 text-xs" style="color: var(--text);">${row.処理種別 || '-'}</td>
          <td class="px-3 py-2 text-xs">${statusBadge}</td>
          <td class="px-3 py-2 text-xs" style="color: var(--text);">${orderNumber}</td>
          <td class="px-3 py-2 text-xs" style="color: var(--text);">${row.処理件数 || 0}</td>
          <td class="px-3 py-2 text-xs" style="color: var(--text);">${row.エラー件数 || 0}</td>
          <td class="px-3 py-2 text-xs" style="color: var(--text);">${executor}</td>
          <td class="px-3 py-2 text-xs">
            <button class="action-btn secondary detail-btn text-xs px-2 py-1" data-id="${row.id}">詳細</button>
            ${row.処理ステータス === '失敗' ? `<button class="action-btn retry-btn text-xs px-2 py-1 ml-1" data-id="${row.id}">再実行</button>` : ''}
          </td>
        </tr>
      `;
    }).join('');
  }

  function getStatusBadge(status) {
    const badges = {
      '成功': '<span class="px-2 py-1 text-xs rounded" style="background: rgba(34, 197, 94, 0.1); color: #22c55e;">成功</span>',
      '失敗': '<span class="px-2 py-1 text-xs rounded" style="background: rgba(239, 68, 68, 0.1); color: #ef4444;">失敗</span>',
      '実行中': '<span class="px-2 py-1 text-xs rounded" style="background: rgba(59, 130, 246, 0.1); color: #3b82f6;">実行中</span>',
      '中断': '<span class="px-2 py-1 text-xs rounded" style="background: rgba(245, 158, 11, 0.1); color: #f59e0b;">中断</span>',
      '再試行中': '<span class="px-2 py-1 text-xs rounded" style="background: rgba(168, 85, 247, 0.1); color: #a855f7;">再試行中</span>'
    };
    return badges[status] || `<span class="px-2 py-1 text-xs rounded" style="background: rgba(107, 114, 128, 0.1); color: #6b7280;">${status}</span>`;
  }

  // 初期データ読み込み
  window.aivicApi.list(5).then(rows => {
    if (rows) renderRows(rows);
  });

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const integrationType = container.querySelector('#integration-type').value;
    const orderNumber = container.querySelector('#order-number').value;
    const statusSuccess = container.querySelector('#status-success').checked;
    const statusFailed = container.querySelector('#status-failed').checked;
    const statusRunning = container.querySelector('#status-running').checked;

    const rows = await window.aivicApi.list(5);
    if (!rows) return;

    const filtered = rows.filter(row => {
      // 日時範囲フィルタ
      if (startDate && row.処理開始日時 && new Date(row.処理開始日時) < new Date(startDate)) return false;
      if (endDate && row.処理開始日時 && new Date(row.処理開始日時) > new Date(endDate)) return false;

      // 連携種別フィルタ
      if (integrationType && row.処理種別 !== integrationType) return false;

      // 発注番号フィルタ
      if (orderNumber && !JSON.stringify(row).toLowerCase().includes(orderNumber.toLowerCase())) return false;

      // ステータスフィルタ
      if ((statusSuccess || statusFailed || statusRunning)) {
        const matchesStatus = 
          (statusSuccess && row.処理ステータス === '成功') ||
          (statusFailed && row.処理ステータス === '失敗') ||
          (statusRunning && row.処理ステータス === '実行中');
        if (!matchesStatus) return false;
      }

      return true;
    });

    renderRows(filtered);
  });

  // 検索条件クリア
  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#start-date').value = '';
    container.querySelector('#end-date').value = '';
    container.querySelector('#integration-type').value = '';
    container.querySelector('#order-number').value = '';
    container.querySelector('#status-success').checked = false;
    container.querySelector('#status-failed').checked = false;
    container.querySelector('#status-running').checked = false;

    window.aivicApi.list(5).then(rows => {
      if (rows) renderRows(rows);
    });
  });

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(5);
    if (!rows) return;

    const headers = ['処理日時', '連携種別', 'ステータス', '対象発注', '処理件数', 'エラー件数', '実行者'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...rows.map(row => [
        row.処理開始日時 ? new Date(row.処理開始日時).toLocaleString('ja-JP') : '',
        row.処理種別 || '',
        row.処理ステータス || '',
        row.対象データID ? `ORD-${row.対象データID.slice(-8)}` : '',
        row.処理件数 || 0,
        row.エラー件数 || 0,
        row.処理実行者ID ? 'システム自動' : '手動実行'
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `連携処理履歴_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  });

  // 詳細表示・再実行のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    const retryBtn = e.target.closest('.retry-btn');

    if (detailBtn) {
      const id = detailBtn.dataset.id;
      const rows = await window.aivicApi.list(5);
      const row = rows?.find(r => r.id === id);
      if (!row) return;

      // 詳細モーダル表示
      showDetailModal(row);
    }

    if (retryBtn) {
      const id = retryBtn.dataset.id;
      if (!confirm('この処理を再実行しますか？')) return;

      // 再実行処理（ステータス更新）
      const updated = await window.aivicApi.update(5, id, {
        処理ステータス: '再試行中',
        再試行回数: 1,
        次回再試行日時: new Date().toISOString()
      });

      if (updated) {
        alert('再実行を開始しました。');
        window.aivicApi.list(5).then(rows => {
          if (rows) renderRows(rows);
        });
      }
    }
  });

  // 詳細モーダル表示
  async function showDetailModal(row) {
    const modal = container.querySelector('#detail-modal');

    // 基本情報設定
    container.querySelector('#detail-id').textContent = row.id || '';
    container.querySelector('#detail-type').textContent = row.処理種別 || '';
    container.querySelector('#detail-status').innerHTML = getStatusBadge(row.処理ステータス || '');

    const startTime = row.処理開始日時 ? new Date(row.処理開始日時) : null;
    const endTime = row.処理終了日時 ? new Date(row.処理終了日時) : null;
    const duration = startTime && endTime ? `${Math.round((endTime - startTime) / 1000)}秒` : '処理中';
    container.querySelector('#detail-duration').textContent = duration;

    // エラー情報表示
    const errorSection = container.querySelector('#error-section');
    if (row.処理ステータス === '失敗' && row.エラーメッセージ) {
      errorSection.style.display = 'block';
      container.querySelector('#error-message').textContent = row.エラーメッセージ;
    } else {
      errorSection.style.display = 'none';
    }

    // データ検証結果表示
    const validationRows = await window.aivicApi.list(8); // データ検証結果テーブル
    const validationTbody = container.querySelector('#validation-tbody');
    if (validationRows) {
      const relatedValidations = validationRows.filter(v => v.連携処理履歴ID === row.id);
      validationTbody.innerHTML = relatedValidations.map(v => `
        <tr>
          <td class="px-2 py-1 text-xs" style="color: var(--text);">${v.検証項目名 || ''}</td>
          <td class="px-2 py-1 text-xs">${getValidationBadge(v.検証結果 || '')}</td>
          <td class="px-2 py-1 text-xs" style="color: var(--text);">${v.検証メッセージ || ''}</td>
        </tr>
      `).join('');
    }

    // リクエスト・レスポンスデータ
    container.querySelector('#request-data').value = row.リクエストデータ || '';
    container.querySelector('#response-data').value = row.レスポンスデータ || '';

    modal.style.display = 'flex';
  }

  function getValidationBadge(result) {
    const badges = {
      '成功': '<span class="px-2 py-1 text-xs rounded" style="background: rgba(34, 197, 94, 0.1); color: #22c55e;">成功</span>',
      '警告': '<span class="px-2 py-1 text-xs rounded" style="background: rgba(245, 158, 11, 0.1); color: #f59e0b;">警告</span>',
      'エラー': '<span class="px-2 py-1 text-xs rounded" style="background: rgba(239, 68, 68, 0.1); color: #ef4444;">エラー</span>'
    };
    return badges[result] || `<span class="px-2 py-1 text-xs rounded" style="background: rgba(107, 114, 128, 0.1); color: #6b7280;">${result}</span>`;
  }

  // モーダル閉じる
  container.querySelector('#close-modal').addEventListener('click', () => {
    container.querySelector('#detail-modal').style.display = 'none';
  });

  // モーダル内のナビゲーション
  container.querySelector('#btn-error-analysis').addEventListener('click', () => {
    window.showScreen('scr-1780291305048');
  });

  container.querySelector('#btn-validation-detail').addEventListener('click', () => {
    window.showScreen('scr-1780291315061');
  });

  // モーダル内の再実行
  container.querySelector('#btn-retry').addEventListener('click', async () => {
    const id = container.querySelector('#detail-id').textContent;
    if (!id || !confirm('この処理を再実行しますか？')) return;

    const updated = await window.aivicApi.update(5, id, {
      処理ステータス: '再試行中',
      再試行回数: 1,
      次回再試行日時: new Date().toISOString()
    });

    if (updated) {
      alert('再実行を開始しました。');
      container.querySelector('#detail-modal').style.display = 'none';
      window.aivicApi.list(5).then(rows => {
        if (rows) renderRows(rows);
      });
    }
  });
}

function(container, apiUrl, tables) {
  let editingNotificationId = null;

  // 通知設定一覧の再描画
  function renderNotificationSettings(rows) {
    const tbody = container.querySelector("#notification-settings-tbody");
    tbody.innerHTML = rows.map(r => {
      const priorityText = r.優先度 === 1 ? "高" : r.優先度 === 2 ? "中" : r.優先度 === 3 ? "低" : "";
      const statusBadge = r.有効フラグ ? 
        '<span style="background: #22c55e; color: #fff; padding: 2px 8px; border-radius: 12px; font-size: 12px;">有効</span>' :
        '<span style="background: #ef4444; color: #fff; padding: 2px 8px; border-radius: 12px; font-size: 12px;">無効</span>';

      return `
        <tr data-id="${r.id || r.通知設定ID}">
          <td>${r.通知名 || ""}</td>
          <td>${r.通知種別 || ""}</td>
          <td>${r.通知対象者種別 || ""}</td>
          <td>${r.通知方法 || ""}</td>
          <td>${priorityText}</td>
          <td>${statusBadge}</td>
          <td>
            <button class="action-btn secondary edit-notification-btn" data-id="${r.id || r.通知設定ID}" style="margin-right: 4px;">編集</button>
            <button class="action-btn secondary delete-notification-btn" data-id="${r.id || r.通知設定ID}">削除</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 通知履歴一覧の再描画
  function renderNotificationHistory(rows) {
    const tbody = container.querySelector("#notification-history-tbody");
    tbody.innerHTML = rows.map(r => {
      const sendDate = r.送信日時 ? new Date(r.送信日時).toLocaleString('ja-JP') : "";
      const statusBadge = r.送信状態 === "送信完了" ? 
        '<span style="background: #22c55e; color: #fff; padding: 2px 8px; border-radius: 12px; font-size: 12px;">送信完了</span>' :
        r.送信状態 === "送信失敗" ?
        '<span style="background: #ef4444; color: #fff; padding: 2px 8px; border-radius: 12px; font-size: 12px;">送信失敗</span>' :
        '<span style="background: #f59e0b; color: #fff; padding: 2px 8px; border-radius: 12px; font-size: 12px;">送信待ち</span>';

      const readBadge = r.既読フラグ ? 
        '<span style="background: #3b82f6; color: #fff; padding: 2px 8px; border-radius: 12px; font-size: 12px;">既読</span>' :
        '<span style="background: #6b7280; color: #fff; padding: 2px 8px; border-radius: 12px; font-size: 12px;">未読</span>';

      return `
        <tr data-id="${r.id || r.通知履歴ID}">
          <td>${sendDate}</td>
          <td>${r.通知タイトル || ""}</td>
          <td>${r.受信者ユーザーID || ""}</td>
          <td>${r.通知種別 || ""}</td>
          <td>${r.送信方法 || ""}</td>
          <td>${statusBadge}</td>
          <td>${readBadge}</td>
          <td>
            <button class="action-btn secondary resend-btn" data-id="${r.id || r.通知履歴ID}">再送</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 初期データ表示
  if (tables[0] && tables[0].records) {
    renderNotificationSettings(tables[0].records);
  }
  if (tables[1] && tables[1].records) {
    renderNotificationHistory(tables[1].records);
  }

  // 通知設定検索
  container.querySelector("#btn-search-notification").addEventListener("click", async () => {
    const keyword = container.querySelector("#input-search-notification").value;
    const rows = await window.aivicApi.list(0);
    if (rows) {
      const filtered = rows.filter(r => 
        JSON.stringify(r).toLowerCase().includes(keyword.toLowerCase())
      );
      renderNotificationSettings(filtered);
    }
  });

  // 通知履歴検索
  container.querySelector("#btn-search-history").addEventListener("click", async () => {
    const keyword = container.querySelector("#input-search-history").value;
    const status = container.querySelector("#select-history-status").value;
    const rows = await window.aivicApi.list(1);
    if (rows) {
      let filtered = rows;
      if (keyword) {
        filtered = filtered.filter(r => 
          JSON.stringify(r).toLowerCase().includes(keyword.toLowerCase())
        );
      }
      if (status) {
        filtered = filtered.filter(r => r.送信状態 === status);
      }
      renderNotificationHistory(filtered);
    }
  });

  // 通知設定保存
  container.querySelector("#btn-save-notification").addEventListener("click", async () => {
    const notificationType = container.querySelector("#select-notification-type").value;
    const targetUserType = container.querySelector("#select-target-user-type").value;
    const notificationMethod = container.querySelector("#select-notification-method").value;
    const notificationName = container.querySelector("#input-notification-name").value;
    const priority = container.querySelector("#select-priority").value;
    const subjectTemplate = container.querySelector("#input-subject-template").value;
    const bodyTemplate = container.querySelector("#textarea-body-template").value;
    const condition = container.querySelector("#textarea-condition").value;
    const activeFlag = container.querySelector("#checkbox-active-flag").checked;

    if (!notificationType || !targetUserType || !notificationMethod || !notificationName) {
      alert("必須項目を入力してください");
      return;
    }

    const data = {
      通知種別: notificationType,
      通知名: notificationName,
      通知対象者種別: targetUserType,
      通知方法: notificationMethod,
      件名テンプレート: subjectTemplate,
      本文テンプレート: bodyTemplate,
      発生条件: condition,
      優先度: parseInt(priority) || 2,
      有効フラグ: activeFlag,
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: "current-user",
      更新者ID: "current-user"
    };

    let result;
    if (editingNotificationId) {
      result = await window.aivicApi.update(0, editingNotificationId, data);
      editingNotificationId = null;
    } else {
      result = await window.aivicApi.save(0, data);
    }

    if (result) {
      // フォームクリア
      container.querySelector("#select-notification-type").value = "";
      container.querySelector("#select-target-user-type").value = "";
      container.querySelector("#select-notification-method").value = "";
      container.querySelector("#input-notification-name").value = "";
      container.querySelector("#select-priority").value = "";
      container.querySelector("#input-subject-template").value = "";
      container.querySelector("#textarea-body-template").value = "";
      container.querySelector("#textarea-condition").value = "";
      container.querySelector("#checkbox-active-flag").checked = false;

      // 一覧更新
      const rows = await window.aivicApi.list(0);
      if (rows) renderNotificationSettings(rows);
    }
  });

  // フォームクリア
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#select-notification-type").value = "";
    container.querySelector("#select-target-user-type").value = "";
    container.querySelector("#select-notification-method").value = "";
    container.querySelector("#input-notification-name").value = "";
    container.querySelector("#select-priority").value = "";
    container.querySelector("#input-subject-template").value = "";
    container.querySelector("#textarea-body-template").value = "";
    container.querySelector("#textarea-condition").value = "";
    container.querySelector("#checkbox-active-flag").checked = false;
    editingNotificationId = null;
  });

  // テスト通知送信
  container.querySelector("#btn-test-notification").addEventListener("click", async () => {
    const testData = {
      通知設定ID: "test-notification",
      受信者ユーザーID: "current-user",
      通知タイトル: "テスト通知",
      通知内容: "これはテスト通知です。",
      通知種別: "システムメンテナンス",
      優先度: "中",
      送信方法: "システム内通知",
      送信状態: "送信完了",
      既読フラグ: false,
      送信予定日時: new Date().toISOString(),
      送信日時: new Date().toISOString(),
      再送回数: 0,
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者: "current-user"
    };

    const result = await window.aivicApi.save(1, testData);
    if (result) {
      alert("テスト通知を送信しました");
      const rows = await window.aivicApi.list(1);
      if (rows) renderNotificationHistory(rows);
    }
  });

  // CSVエクスポート
  container.querySelector("#btn-csv-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (rows && rows.length > 0) {
      const headers = ["通知名", "通知種別", "通知対象者種別", "通知方法", "優先度", "有効フラグ", "件名テンプレート", "本文テンプレート", "発生条件"];
      const csvContent = "\uFEFF" + [
        headers.join(","),
        ...rows.map(r => [
          `"${r.通知名 || ""}"`,
          `"${r.通知種別 || ""}"`,
          `"${r.通知対象者種別 || ""}"`,
          `"${r.通知方法 || ""}"`,
          `"${r.優先度 || ""}"`,
          `"${r.有効フラグ ? "有効" : "無効"}"`,
          `"${r.件名テンプレート || ""}"`,
          `"${r.本文テンプレート || ""}"`,
          `"${r.発生条件 || ""}"`
        ].join(","))
      ].join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = "notification_settings.csv";
      link.click();
    }
  });

  // イベントデリゲーション（編集・削除・再送）
  container.addEventListener("click", async (e) => {
    // 通知設定編集
    const editBtn = e.target.closest(".edit-notification-btn");
    if (editBtn) {
      const id = editBtn.dataset.id;
      const rows = await window.aivicApi.list(0);
      if (rows) {
        const row = rows.find(r => (r.id || r.通知設定ID) === id);
        if (row) {
          container.querySelector("#select-notification-type").value = row.通知種別 || "";
          container.querySelector("#select-target-user-type").value = row.通知対象者種別 || "";
          container.querySelector("#select-notification-method").value = row.通知方法 || "";
          container.querySelector("#input-notification-name").value = row.通知名 || "";
          container.querySelector("#select-priority").value = row.優先度 || "";
          container.querySelector("#input-subject-template").value = row.件名テンプレート || "";
          container.querySelector("#textarea-body-template").value = row.本文テンプレート || "";
          container.querySelector("#textarea-condition").value = row.発生条件 || "";
          container.querySelector("#checkbox-active-flag").checked = row.有効フラグ || false;
          editingNotificationId = id;
        }
      }
    }

    // 通知設定削除
    const deleteBtn = e.target.closest(".delete-notification-btn");
    if (deleteBtn) {
      if (!confirm("この通知設定を削除しますか？")) return;
      const id = deleteBtn.dataset.id;
      await window.aivicApi.delete(0, id);
      const rows = await window.aivicApi.list(0);
      if (rows) renderNotificationSettings(rows);
    }

    // 通知再送
    const resendBtn = e.target.closest(".resend-btn");
    if (resendBtn) {
      if (!confirm("この通知を再送しますか？")) return;
      const id = resendBtn.dataset.id;
      const rows = await window.aivicApi.list(1);
      if (rows) {
        const row = rows.find(r => (r.id || r.通知履歴ID) === id);
        if (row) {
          const updatedData = {
            ...row,
            送信状態: "送信完了",
            送信日時: new Date().toISOString(),
            再送回数: (row.再送回数 || 0) + 1,
            更新日時: new Date().toISOString()
          };
          await window.aivicApi.update(1, id, updatedData);
          const updatedRows = await window.aivicApi.list(1);
          if (updatedRows) renderNotificationHistory(updatedRows);
        }
      }
    }
  });

  // 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    if (rows) renderNotificationSettings(rows);
  });

  window.aivicApi.list(1).then(rows => {
    if (rows) renderNotificationHistory(rows);
  });
}
